When indexing assets or records into a map/object by an ID, normalize the input collection using an array helper (e.g., `asArray`), filter out non-record entries, and ensure only entries with a non-empty ID string are indexed to prevent malformed or empty keys. Additionally, filter the fixtures array to record-only entries before mapping to prevent TypeErrors.

```javascript
function allowedPathQueryReceipt({ rows, revealGatePolicy, frontendFixtures }) {
  const recordRows = asArray(rows).filter(isRecord);
  const pageLocatedRows = recordRows.filter((row) => (
    row.locator_status === 'exact_located' || row.locator_status === 'page_located'
  )).length;
  const states = new Map(
    asArray(revealGatePolicy?.reveal_eligibility_states)
      .filter((state) => isRecord(state) && typeof state.state === 'string' && state.state.trim() !== '')
      .map((state) => [state.state, state])
  );
  const fixtureIds = new Set(
    asArray(frontendFixtures?.fixtures)
      .filter(isRecord)
      .map((fixture) => fixture.fixture_id)
      .filter((id) => typeof id === 'string' && id !== '')
  );
  return {
    submitted_answer_allowed_count:
      states.get('submitted_answer_reveal_allowed')?.reveal_allowed === true
        ? pageLocatedRows
        : 0,
    student_confirmed_attempt_allowed_count:
      states.get('student_confirmed_attempt_reveal_allowed')?.reveal_allowed === true
        ? pageLocatedRows
        : 0,
    pre_attempt_allowed_count:
      states.get('pre_attempt_blocked')?.reveal_allowed === true ? pageLocatedRows : 0,
    submitted_answer_fixture_queryable:
      fixtureIds.has('submitted_answer_reveal_allowed') &&
      fixtureIds.has('reveal_authorized_route_submitted_answer_allowed'),
    student_confirmed_attempt_fixture_queryable:
      fixtureIds.has('student_confirmed_attempt_reveal_allowed') &&
      fixtureIds.has('reveal_authorized_route_student_confirmed_allowed'),
  };
}
