```javascript
export function validatePostAttemptMsRevealReadModelRehearsal({ receipt } = {}) {
  if (!isRecord(receipt)) return failResult(['receipt_required']);
  const errors = [];
  const summary = receipt.rehearsal_summary ?? {};

  if (summary.total_ms_reveal_payload_row_count !== EXPECTED_ROW_COUNT) {
    errors.push('total_ms_reveal_payload_row_count_not_3530');
  }
  if (summary.missing_ms_reveal_payload_row_count !== 0) {
    errors.push('missing_ms_reveal_payload_row_count_not_zero');
  }
  if (summary.duplicate_question_key_count !== 0) {
    errors.push('duplicate_question_key_count_not_zero');
  }
  errors.push(...zeroFieldErrors(
    receipt,
    'resource_access_receipt',
    REQUIRED_ZERO_FIELDS.resource_access_receipt,
  ));
  errors.push(...zeroFieldErrors(
    receipt,
    'boundary_receipt',
    REQUIRED_ZERO_FIELDS.boundary_receipt,
  ));
  errors.push(...zeroFieldErrors(
    receipt,
    'side_effect_receipt',
    REQUIRED_ZERO_FIELDS.side_effect_receipt,
  ));
  if (receipt.side_effect_receipt?.remote_disposable_write_authorized !== false) {
    errors.push('remote_disposable_write_authorized_without_gate');
  }
  if (
    receipt.side_effect_receipt?.authorization_required_before_remote_disposable_write !== true
  ) {
    errors.push('remote_disposable_authorization_gate_missing');
  }
  expectedCount(receipt, ['rehearsal_summary', 'accepted_crop_without_visual_qa_count'], 0, 'accepted_crop_without_visual_qa_count_not_zero', errors);
  expectedCount(receipt, ['rehearsal_summary', 'student_display_candidate_without_visual_qa_count'], 0, 'student_display_candidate_without_visual_qa_count_not_zero', errors);

  let sourceArtifacts = [];
  if ('source_artifacts' in receipt) {
    if (!Array.isArray(receipt.source_artifacts)) {
      errors.push('source_artifacts_invalid_type');
    } else {
      sourceArtifacts = receipt.source_artifacts;
    }
  }

  const expectedRoles = [
    'post_attempt_ms_question_source_inventory',
    'post_attempt_ms_question_source_inventory_validator',
    'post_attempt_ms_page_source_reveal_assets',
    'post_attempt_ms_page_source_reveal_assets_validator',
    'post_attempt_ms_page_source_reveal_assets_visual_qa',
    'post_attempt_ms_reveal_gate_policy',
    'post_attempt_ms_reveal_gate_policy_validator',
    'post_attempt_ms_display_policy',
    'post_attempt_ms_display_policy_validator',
    'post_attempt_ms_page_first_crop_candidates',
    'post_attempt_ms_page_first_crop_candidates_validator',
    'post_attempt_ms_crop_quality_gate',
    'post_attempt_ms_crop_quality_gate_validator',
    'post_attempt_ms_self_assessment_copilot_boundary',
    'post_attempt_ms_self_assessment_copilot_boundary_validator',
    'post_attempt_ms_source_reveal_frontend_fixtures',
    'post_attempt_ms_source_reveal_frontend_fixtures_manifest',
    'post_attempt_ms_source_reveal_frontend_fixtures_validator',
  ];

  const presentRoles = new Set(sourceArtifacts.map((a) => a?.role));
  const allExpectedRolesPresent = expectedRoles.every((role) => presentRoles.has(role));
  if (!allExpectedRolesPresent) {
    errors.push('source_artifacts_missing_expected_roles');
  }

  const allRowsLoaded =
    summary.total_ms_reveal_payload_row_count === EXPECTED_ROW_COUNT &&
    summary.expected_ms_reveal_payload_row_count === EXPECTED_ROW_COUNT &&
    summary.missing_ms_reveal_payload_row_count === 0 &&
    summary.duplicate_question_key_count === 0;
  const inputArtifactsLoadedAndValidated =
    allExpectedRolesPresent &&
    sourceArtifacts.length > 0 &&
    sourceArtifacts.every((artifact) => (
      artifact?.exists === true &&
      artifact?.loaded === true &&
      /^[a-f0-9]{64}$/u.test(String(artifact?.sha256 ?? '')) &&
      (artifact?.validator_artifact !== true || artifact?.validator_status === 'pass')
    ));
