+
+function writeText(root, relPath, text) {
+  const outPath = resolvePath(root, relPath);
+  fs.mkdirSync(path.dirname(outPath), { recursive: true });
+  fs.writeFileSync(outPath, text.endsWith('\n') ? text : `${text}\n`, 'utf8');
+}
+
+function sortedObject(object) {
+  return Object.fromEntries(Object.entries(object).sort(([left], [right]) => (
+    Buffer.compare(Buffer.from(left, 'utf8'), Buffer.from(right, 'utf8'))
+  )));
+}
+
+function countBy(rows, selector) {
+  const counts = {};
+  for (const row of asArray(rows)) {
+    const value = selector(row);
+    const key = value === null || value === undefined || value === ''
+      ? 'missing'
+      : String(value);
+    counts[key] = (counts[key] ?? 0) + 1;
+  }
+  return sortedObject(counts);
+}
+
+function duplicateCount(values) {
+  const seen = new Set();
+  const duplicates = new Set();
+  for (const value of values) {
+    if (typeof value !== 'string' || value.length === 0) continue;
+    if (seen.has(value)) duplicates.add(value);
+    seen.add(value);
+  }
+  return duplicates.size;
+}
+
+function sumCounts(counts) {
+  return Object.values(counts ?? {}).reduce((sum, value) => sum + Number(value ?? 0), 0);
+}
+
+function validatorPasses(payload) {
+  const status = payload?.validator_status ?? payload?.summary?.validation_status ?? null;
+  const failCount = Number(
+    payload?.summary?.check_fail_count ??
+    payload?.summary?.failed_check_count ??
+    payload?.summary?.validation_error_count ??
+    0,
+  );
+  return status === 'pass' && failCount === 0;
+}
+
+function sourceArtifact(root, role, relPath, value, validatorRole = false) {
+  const exists = fs.existsSync(resolvePath(root, relPath));
+  return {
+    role,
+    path: relPath,
+    exists,
+    loaded: isRecord(value),
+    validator_artifact: validatorRole,
+    validator_status: validatorRole ? value?.validator_status ?? null : null,
+    sha256: exists ? sha256File(root, relPath) : null,
+  };
+}
+
+function loadInputs(root, paths) {
+  const inputs = {
+    questionSourceInventory: readJson(root, paths.questionSourceInventoryIn),
+    questionSourceInventoryValidator: readJson(root, paths.questionSourceInventoryValidatorIn),
+    pageSourceRevealAssets: readJson(root, paths.pageSourceRevealAssetsIn),
+    pageSourceRevealAssetsValidator: readJson(root, paths.pageSourceRevealAssetsValidatorIn),
+    pageSourceRevealAssetsVisualQa: readJson(root, paths.pageSourceRevealAssetsVisualQaIn),
+    revealGatePolicy: readJson(root, paths.revealGatePolicyIn),
+    revealGatePolicyValidator: readJson(root, paths.revealGatePolicyValidatorIn),
+    displayPolicy: readJson(root, paths.displayPolicyIn),
+    displayPolicyValidator: readJson(root, paths.displayPolicyValidatorIn),
+    cropCandidates: readJson(root, paths.cropCandidatesIn),
+    cropCandidatesValidator: readJson(root, paths.cropCandidatesValidatorIn),
+    cropQualityGate: readJson(root, paths.cropQualityGateIn),
+    cropQualityGateValidator: readJson(root, paths.cropQualityGateValidatorIn),
+    selfAssessmentCopilotBoundary: readJson(root, paths.selfAssessmentCopilotBoundaryIn),
+    selfAssessmentCopilotValidator: readJson(root, paths.selfAssessmentCopilotValidatorIn),
+    frontendFixtures: readJson(root, paths.frontendFixturesIn),
+    frontendFixturesManifest: readJson(root, paths.frontendFixturesManifestIn),
+    frontendFixturesValidator: readJson(root, paths.frontendFixturesValidatorIn),
+  };
+  inputs.sourceArtifacts = [
+    ['post_attempt_ms_question_source_inventory', paths.questionSourceInventoryIn, inputs.questionSourceInventory, false],
+    ['post_attempt_ms_question_source_inventory_validator', paths.questionSourceInventoryValidatorIn, inputs.questionSourceInventoryValidator, true],
+    ['post_attempt_ms_page_source_reveal_assets', paths.pageSourceRevealAssetsIn, inputs.pageSourceRevealAssets, false],
+    ['post_attempt_ms_page_source_reveal_assets_validator', paths.pageSourceRevealAssetsValidatorIn, inputs.pageSourceRevealAssetsValidator, true],
+    ['post_attempt_ms_page_source_reveal_assets_visual_qa', paths.pageSourceRevealAssetsVisualQaIn, inputs.pageSourceRevealAssetsVisualQa, false],
+    ['post_attempt_ms_reveal_gate_policy', paths.revealGatePolicyIn, inputs.revealGatePolicy, false],
+    ['post_attempt_ms_reveal_gate_policy_validator', paths.revealGatePolicyValidatorIn, inputs.revealGatePolicyValidator, true],
+    ['post_attempt_ms_display_policy', paths.displayPolicyIn, inputs.displayPolicy, false],
+    ['post_attempt_ms_display_policy_validator', paths.displayPolicyValidatorIn, inputs.displayPolicyValidator, true],
+    ['post_attempt_ms_page_first_crop_candidates', paths.cropCandidatesIn, inputs.cropCandidates, false],
+    ['post_attempt_ms_page_first_crop_candidates_validator', paths.cropCandidatesValidatorIn, inputs.cropCandidatesValidator, true],
+    ['post_attempt_ms_crop_quality_gate', paths.cropQualityGateIn, inputs.cropQualityGate, false],
+    ['post_attempt_ms_crop_quality_gate_validator', paths.cropQualityGateValidatorIn, inputs.cropQualityGateValidator, true],
+    ['post_attempt_ms_self_assessment_copilot_boundary', paths.selfAssessmentCopilotBoundaryIn, inputs.selfAssessmentCopilotBoundary, false],
+    ['post_attempt_ms_self_assessment_copilot_boundary_validator', paths.selfAssessmentCopilotValidatorIn, inputs.selfAssessmentCopilotValidator, true],
+    ['post_attempt_ms_source_reveal_frontend_fixtures', paths.frontendFixturesIn, inputs.frontendFixtures, false],
+    ['post_attempt_ms_source_reveal_frontend_fixtures_manifest', paths.frontendFixturesManifestIn, inputs.frontendFixturesManifest, false],
+    ['post_attempt_ms_source_reveal_frontend_fixtures_validator', paths.frontendFixturesValidatorIn, inputs.frontendFixturesValidator, true],
+  ].map(([role, relPath, value, validatorRole]) => (
+    sourceArtifact(root, role, relPath, value, validatorRole)
+  ));
+  return inputs;
+}
+
+function rowReviewQueueBucket(row) {
+  if (row?.locator_status === 'exact_located' || row?.locator_status === 'page_located') {
+    return 'post_attempt_ms_page_source_candidate_review';
+  }
+  return row?.review_queue?.queue_id ?? 'missing';
+}
+
+function buildCounts({ rows, pageAssets, cropQualityRecords, displayDecisions }) {
+  const pageLocatedRows = rows.filter((row) => (
+    row.locator_status === 'exact_located' || row.locator_status === 'page_located'
+  )).length;
+  return {
+    locator_status: countBy(rows, (row) => row.locator_status),
+    page_asset_status: countBy(pageAssets, (asset) => asset.student_display_posture),
+    crop_status: countBy(cropQualityRecords, (record) => record.crop_status),
+    crop_quality_status: countBy(cropQualityRecords, (record) => record.crop_quality_status),
+    reveal_eligibility: sortedObject({
+      missing_ambiguous_unavailable: EXPECTED_ROW_COUNT - pageLocatedRows,
+      submitted_answer_reveal_allowed: pageLocatedRows,
+      student_confirmed_attempt_reveal_allowed: pageLocatedRows,
+    }),
+    display_policy_posture: countBy(
+      displayDecisions,
+      (decision) => decision.display_policy?.posture,
+    ),
+    disable_state: countBy(displayDecisions, (decision) => (
+      decision.display_controls?.disabled_for_student_display === true
+        ? 'disabled_for_student_display'
+        : 'enabled_for_policy_evaluation'
+    )),
+    post_attempt_review_mode: sortedObject({
+      page_source_candidate_review: pageLocatedRows,
+      source_backfill_review: EXPECTED_ROW_COUNT - pageLocatedRows,
+    }),
+    display_mode: countBy(rows, (row) => row.ms_source_reveal_display_mode),
+    fallback_mode: sortedObject({
+      page_fallback: cropQualityRecords.filter((record) => (
+        record.page_level_fallback?.available === true
+      )).length,
+      unavailable: rows.filter((row) => row.ms_source_reveal_display_mode === 'unavailable').length,
+    }),
+    review_queue: countBy(rows, rowReviewQueueBucket),
+  };
+}
+
+function hasPublicReference(record) {
+  const values = [
+    record?.public_url,
+    record?.static_asset_path,
+    record?.pre_attempt_fetch_reference,
+    record?.controlled_reference?.public_static_url,
+    record?.controlled_reference?.pre_attempt_fetch_reference,
+  ];
+  return values.some((value) => typeof value === 'string' && value.length > 0);
+}
+
+function resourceAccessReceipt({ pageAssets, cropCandidates, cropQualityRecords, revealGatePolicy, frontendFixtures }) {
+  const fixtureItems = asArray(frontendFixtures?.fixtures);
+  const assetLikeRecords = [
+    ...pageAssets,
+    ...cropCandidates,
+    ...cropQualityRecords,
+  ];
+  const preAttemptPayloadAssetExposureCount = fixtureItems.filter((fixture) => (
+    fixture.fixture_id?.includes('pre_attempt') &&
+    (
+      fixture.reveal_gate?.reveal_allowed === true ||
+      fixture.display?.student_ms_source_visible === true ||
+      fixture.source_view?.controlled_asset_ref
+    )
+  )).length;
+  return {
+    pre_attempt_payload_asset_exposure_count: preAttemptPayloadAssetExposureCount,
+    pre_attempt_direct_fetch_allowed_count: assetLikeRecords.filter((record) => (
+      record.asset_delivery?.pre_attempt_fetch_allowed === true ||
+      record.pre_attempt_fetch_reference
+    )).length + (
+      revealGatePolicy?.resource_fetch_gate?.pre_attempt_direct_fetch_allowed === true ? 1 : 0
+    ),
+    public_static_guessable_url_count: assetLikeRecords.filter((record) => (
+      record.asset_delivery?.public_static_url_allowed === true || hasPublicReference(record)
+    )).length + (
+      revealGatePolicy?.resource_fetch_gate?.public_static_or_guessable_asset_path_allowed === true ? 1 : 0
+    ),
+    frontend_preload_static_props_route_loader_client_bundle_exposure_count:
+      assetLikeRecords.filter((record) => (
+        record.asset_delivery?.preload_in_frontend_bundle_allowed === true
+      )).length +
+      Object.values(revealGatePolicy?.frontend_exposure_policy ?? {})
+        .filter((value) => value === true).length,
+    teacher_admin_preview_student_role_bypass_count:
+      revealGatePolicy?.viewer_context?.role_authorized_for_preview?.student === true ? 1 : 0,
+  };
+}
+
+function allowedPathQueryReceipt({ rows, revealGatePolicy, frontendFixtures }) {
+  const pageLocatedRows = rows.filter((row) => (
+    row.locator_status === 'exact_located' || row.locator_status === 'page_located'
+  )).length;
+  const states = new Map(asArray(revealGatePolicy?.reveal_eligibility_states).map((state) => [
+    state.state,
+    state,
+  ]));
+  const fixtureIds = new Set(asArray(frontendFixtures?.fixtures).map((fixture) => fixture.fixture_id));
+  return {
+    submitted_answer_allowed_count:
+      states.get('submitted_answer_reveal_allowed')?.reveal_allowed === true
+        ? pageLocatedRows
+        : 0,
+    student_confirmed_attempt_allowed_count:
+      states.get('student_confirmed_attempt_reveal_allowed')?.reveal_allowed === true
+        ? pageLocatedRows
+        : 0,
+    pre_attempt_allowed_count:
+      states.get('pre_attempt_blocked')?.reveal_allowed === true ? pageLocatedRows : 0,
+    submitted_answer_fixture_queryable:
+      fixtureIds.has('submitted_answer_reveal_allowed') &&
+      fixtureIds.has('reveal_authorized_route_submitted_answer_allowed'),
+    student_confirmed_attempt_fixture_queryable:
+      fixtureIds.has('student_confirmed_attempt_reveal_allowed') &&
+      fixtureIds.has('reveal_authorized_route_student_confirmed_allowed'),
+  };
+}
+
+function frontendFixtureQueryReceipt(frontendFixtures) {
+  const fixtures = asArray(frontendFixtures?.fixtures);
+  const fixtureIds = new Set(fixtures.map((fixture) => fixture.fixture_id));
+  const queryable = fixtures.filter((fixture) => (
+    typeof fixture.fixture_id === 'string' &&
+    fixture.fixture_id.length > 0 &&
+    asArray(fixture.source_basis?.source_artifact_refs).length > 0
+  ));
+  return {
+    fixture_count: fixtures.length,
+    queryable_fixture_count: queryable.length,
+    submitted_answer_fixture_queryable: fixtureIds.has('submitted_answer_reveal_allowed'),
+    student_confirmed_attempt_fixture_queryable:
+      fixtureIds.has('student_confirmed_attempt_reveal_allowed'),
+    pre_attempt_blocked_fixture_queryable: fixtureIds.has('pre_attempt_blocked'),
+    fixture_ids: [...fixtureIds].sort(),
+  };
+}
+
+function boundaryReceipt({ selfAssessmentCopilotBoundary, frontendFixtures }) {
+  const fixtures = asArray(frontendFixtures?.fixtures);
+  const sideEffects = selfAssessmentCopilotBoundary?.side_effect_receipt ?? {};
+  const runtime = selfAssessmentCopilotBoundary?.runtime_execution_boundary ?? {};
+  return {
+    self_assessment_secure_exam_ready_uplift_count:
+      fixtures.filter((fixture) => (
+        fixture.self_assessment?.can_raise_secure_or_exam_ready === true
+      )).length + (
+        selfAssessmentCopilotBoundary?.self_assessment_learning_effect
+          ?.can_raise_secure_or_exam_ready === true ? 1 : 0
+      ),
+    copilot_ocr_vlm_external_model_execution_count:
+      Number(sideEffects.ocr_or_vlm_call_count ?? 0) +
+      Number(sideEffects.external_model_call_count ?? 0) +
+      Number(sideEffects.runtime_copilot_answer_generation_count ?? 0) +
+      (runtime.ocr_or_vlm_execution_allowed === true ? 1 : 0),
+    automatic_scoring_claim_count:
+      Number(frontendFixtures?.summary?.automatic_scoring_claim_count ?? 0),
+    smart_mark_readiness_claim_count:
+      Number(frontendFixtures?.summary?.smart_mark_production_ready_fixture_count ?? 0) +
+      Number(sideEffects.smart_mark_readiness_mutation_count ?? 0),
+    raw_ms_text_storage_count:
+      Number(frontendFixtures?.summary?.raw_ms_text_storage_fixture_count ?? 0) +
+      Number(sideEffects.raw_ms_text_storage_count ?? 0),
+  };
+}
+
+function sideEffectReceipt() {
+  return {
+    production_supabase_mutation: 0,
+    remote_supabase_mutation: 0,
+    remote_disposable_supabase_write: 0,
+    local_supabase_mutation: 0,
+    production_rag_reindex: 0,
+    vector_mutation: 0,
+    full_frontend_ui_integration: 0,
+    external_model_call_count: 0,
+    ocr_or_vlm_call_count: 0,
+    raw_ms_text_storage_count: 0,
+    production_scoring_mutation_count: 0,
+    smart_mark_readiness_mutation_count: 0,
+    remote_disposable_write_authorized: false,
+    authorization_required_before_remote_disposable_write: true,
+  };
+}
+
+function buildRehearsalSummary(inputs) {
+  const rows = asArray(inputs.questionSourceInventory?.rows);
+  const pageAssets = asArray(inputs.pageSourceRevealAssets?.page_assets);
+  const cropCandidates = asArray(inputs.cropCandidates?.crop_candidates);
+  const cropQualityRecords = asArray(inputs.cropQualityGate?.crop_quality_gate_records);
+  const displayDecisions = asArray(inputs.displayPolicy?.asset_display_decisions);
+  const inventorySummary = inputs.questionSourceInventory?.summary ?? {};
+  const pageAssetSummary = inputs.pageSourceRevealAssets?.summary ?? {};
+  const cropQualitySummary = inputs.cropQualityGate?.summary ?? {};
+  const visualQaReceipt = inputs.pageSourceRevealAssetsVisualQa ?? {};
+  return {
+    total_ms_reveal_payload_row_count: rows.length,
+    expected_ms_reveal_payload_row_count: EXPECTED_ROW_COUNT,
+    missing_ms_reveal_payload_row_count: Math.max(0, EXPECTED_ROW_COUNT - rows.length),
+    duplicate_question_key_count: duplicateCount(rows.map((row) => row.question_key)),
+    unique_ms_page_asset_count:
+      Number(pageAssetSummary.unique_ms_page_asset_count ?? pageAssets.length),
+    duplicate_page_asset_prevented_count:
+      Number(pageAssetSummary.duplicate_page_asset_prevented_count ?? 0),
+    same_page_multiple_questions_exposure_count:
+      Number(inventorySummary.same_page_multiple_question_exposure_count ?? 0),
+    whole_document_exposure_count:
+      Number(inventorySummary.whole_document_exposure_count ?? 0),
+    page_reveal_with_neighbor_answer_exposure_count:
+      Number(inventorySummary.page_reveal_with_neighbor_answer_exposure_count ?? 0),
+    document_only_student_reveal_allowed_count:
+      Number(inventorySummary.document_only_student_reveal_allowed_count ?? 0),
+    generated_screenshot_count:
+      Number(pageAssetSummary.generated_screenshot_count ?? 0) +
+      Number(inputs.cropQualityGate?.side_effect_receipt?.generated_screenshot_count ?? 0),
+    codex_worker_visual_qa_required_count:
+      pageAssets.filter((asset) => asset.codex_worker_visual_qa_required === true).length,
+    codex_worker_visual_qa_receipt_count:
+      Number(visualQaReceipt.visually_inspected_screenshot_count ?? 0),
+    visual_qa_pass_count: Number(visualQaReceipt.visual_qa_pass_count ?? 0),
+    visual_qa_fail_count: Number(visualQaReceipt.visual_qa_fail_count ?? 0),
+    student_display_candidate_without_visual_qa_count:
+      Number(cropQualitySummary.student_display_candidate_without_visual_qa_count ?? 0),
+    accepted_crop_without_visual_qa_count:
+      Number(cropQualitySummary.accepted_crop_without_visual_qa_count ?? 0),
+    counts: buildCounts({
+      rows,
+      pageAssets,
+      cropQualityRecords,
+      displayDecisions,
+      cropCandidates,
+    }),
+  };
+}
